--Find products that have the same price as another product

SELECT
    p1.productid,
    p1.productname,
    p1.price
FROM product__ p1
WHERE EXISTS (
    SELECT 1
    FROM product__ p2
    WHERE p2.price = p1.price
      AND p2.productid <> p1.productid
);

--Calculate the total profit generated by each customer

SELECT
    c.customerid,
    c.customername,
    SUM(o.quantity * (p.price - p.costprice))
        AS total_profit
FROM customer__ c
JOIN order__ o
    ON c.customerid = o.customerid
JOIN product__ p
    ON o.productid = p.productid
GROUP BY c.customerid, c.customername
ORDER BY total_profit DESC;